class Solution {
int gcdValue(int a,int b){while(b){int r=a%b;a=b;b=r;}return a;}
public:
 int maxScore(vector<int>& nums){
  int n=nums.size(),full=(1<<n)-1;vector<int> dp(1<<n,-1);dp[0]=0;
  for(int mask=0;mask<=full;++mask){if(dp[mask]<0)continue;
   int step=__builtin_popcount((unsigned)mask)/2+1;
   for(int i=0;i<n;++i)if(!(mask>>i&1))for(int j=i+1;j<n;++j)if(!(mask>>j&1)){
    int next=mask|(1<<i)|(1<<j);
    dp[next]=max(dp[next],dp[mask]+step*gcdValue(nums[i],nums[j]));
   }
  }return dp[full];
 }
};
